package servicio;
import dao.*;import java.util.List;import java.util.regex.Pattern;import negocio.*;
public class IntentoPagoService {private static final Pattern SENSIBLE=Pattern.compile("(?i)(access[_-]?token|authorization|password|secret|api[_-]?key)\\s*[:=]\\s*[^,;\\s]+");private final IntentoPagoDAO dao;public IntentoPagoService(){this(new IntentoPagoDAOMySQL());}public IntentoPagoService(IntentoPagoDAO d){if(d==null)throw new IllegalArgumentException("El DAO es obligatorio.");dao=d;}public IntentoPago iniciar(long ordenId){return dao.iniciar(ordenId);}public void exitoso(long id,String referencia){dao.finalizar(id,EstadoIntentoPago.CHECKOUT_CREADO,referencia,null);}public void error(long id,String detalle){dao.finalizar(id,EstadoIntentoPago.ERROR,null,redactar(detalle));}public List<IntentoPago> listar(long ordenId){return dao.listarPorOrden(ordenId);}String redactar(String v){if(v==null||v.isBlank())return "Error del proveedor sin detalle.";String x=SENSIBLE.matcher(v).replaceAll("$1=[REDACTADO]");return x.length()>500?x.substring(0,500):x;}}
